function.arguments:
{"command": "cat > submission/transform.jq << 'EOF'
[
  inputs
  | .vector as $v
  | .entry.account_id as $id
  | {key: $id, value: [$v[1], $v[2], $v[3], $v[4]]} 
]
| from_entries
| {vectors: .}
EOF

jq -s -f submission/transform.jq submission/answers.json.tmp > submission/answers.json", "timeout": 10}
